import sys

def solve():
    input_data = sys.stdin.read().split()
    if not input_data:
        return

    iterator = iter(input_data)
    try:
        T = int(next(iterator))
    except StopIteration:
        return

    results = []

    for _ in range(T):
        try:
            N = int(next(iterator))
            W = []
            for _ in range(N):
                W.append(int(next(iterator)))
        except StopIteration:
            break

        min_start_velocity = 0
        for i in range(N):
            required_velocity_at_i = W[i] + (N - 1 - i)
            if required_velocity_at_i > min_start_velocity:
                min_start_velocity = required_velocity_at_i

        results.append(str(min_start_velocity))

    sys.stdout.write('\n'.join(results) + '\n')

if __name__ == "__main__":
    solve()
